import java.util.Scanner;

public class Main {
    // 计算 x 的封闭区域数
    private static int closedCnt(int x) {
        if (x == 0) return 1;
        int cnt = 0;
        while (x > 0) {
            int r = x % 10;
            if (r == 0 || r == 6 || r == 9) cnt += 1;
            else if (r == 8) cnt += 2;
            x /= 10;
        }
        return cnt;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        long baseSum = 0;       // 原始总和，可用 long 防溢出
        long curGain = 0;
        long maxGain = 0;

        for (int val : a) {
            int base = closedCnt(val);
            baseSum += base;
            int delta = closedCnt(val + 1) - base;
            curGain += delta;
            if (curGain > maxGain) maxGain = curGain;
            if (curGain < 0) curGain = 0;
        }

        System.out.println(baseSum + maxGain);
    }
}
